def snake_to_pascal(s):
    result = []
    capitalize_next = True
    for ch in s:
        if ch == '_':
            capitalize_next = True
            continue
        result.append(ch.upper() if capitalize_next else ch.lower())
        capitalize_next = False
    return ''.join(result)

