def is_valid_date(year, month, day):
    if not (1 <= month <= 12) or year < 1 or day < 1:
        return False
    leap = year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
    max_day = _DAYS[month] + (1 if month == 2 and leap else 0)
    return day <= max_day

