def nth_weekday_from_end(year, month, weekday_num, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def sakamoto_weekday(y, m, d):
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        yy = y - 1 if m < 3 else y
        w = (yy + yy // 4 - yy // 100 + yy // 400 + t[m - 1] + d) % 7
        return (w - 1) % 7
    days_in_month = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    first_wd = sakamoto_weekday(year, month, 1)
    matches = [d for d in range(1, days_in_month + 1) if (first_wd + d - 1) % 7 == weekday_num]
    return matches[-n]

