def decimal_to_base(n, base):
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'

    def convert(x):
        if x == 0:
            return ''
        return convert(x // base) + digits[x % base]

    if n == 0:
        return '0'
    if n < 0:
        return '-' + convert(-n)
    return convert(n)
